w:Workflows.w:Workflow:
{
  "triggers": [
    {
      "type": "itemUpdated",
      "concurrency": "skip",
      "list": "Receipts",
      "changedFields": [
        "tags"
      ],
      "terms": [
        "Receipts/Tags/{parameter:Tag}"
      ]
    },
    {
      "type": "document.added",
      "list": "Receipts",
      "data": {
        "source": "upload"
      }
    }
  ],
  "concurrency": "replace",
  "flow": {
    "start": "prepare",
    "nodes": {
      "read": {
        "activity": "ai.prompt",
        "inputs": {
          "execution": "batch",
          "onDeadline": "fail",
          "deadlineHours": 48,
          "system": "You read shop receipts (tickets) from photos and scans of them. Use only what the receipt says.",
          "prompt": "Read this receipt: the store, the purchase date, the currency, the total, and every item line with its description, quantity, unit price and amount. Leave out lines that are not items (subtotals, taxes, payment, change).",
          "includeContent": false,
          "includeImages": 2,
          "schema": {
            "type": "object",
            "properties": {
              "store": {
                "type": "string",
                "description": "The store or company name as printed."
              },
              "date": {
                "type": "string",
                "description": "The purchase date as yyyy-MM-dd.",
                "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
              },
              "currency": {
                "type": "string",
                "description": "ISO 4217 code, e.g. EUR.",
                "pattern": "^[A-Z]{3}$"
              },
              "total": {
                "type": "number",
                "description": "The total paid."
              },
              "lines": {
                "type": "array",
                "items": {
                  "type": "object",
                  "properties": {
                    "description": {
                      "type": "string"
                    },
                    "quantity": {
                      "type": "number"
                    },
                    "unitPrice": {
                      "type": "number"
                    },
                    "amount": {
                      "type": "number",
                      "description": "The line's amount as printed."
                    }
                  },
                  "required": [
                    "description",
                    "quantity",
                    "amount"
                  ]
                }
              }
            },
            "required": [
              "store",
              "date",
              "currency",
              "total",
              "lines"
            ]
          }
        },
        "next": {
          "done": "save",
          "error": "review"
        }
      },
      "save": {
        "activity": "script",
        "inputs": {
          "code": [
            "const receipt = steps.read.json;",
            "await items.update(item.list, item.id, { store: receipt.store, purchaseDate: receipt.date, currency: receipt.currency, total: receipt.total, status: 'Read' });",
            "// Reading again replaces the lines of an earlier reading.",
            "let cursor;",
            "do {",
            "  const page = await items.related(item.id, { type: 'contains receipt line', direction: 'outgoing', top: 500, cursor });",
            "  for (const edge of page.value) {",
            "    await items.unrelate(item.id, edge.id);",
            "    await items.deleteById(edge.item.id);",
            "  }",
            "  cursor = page.nextCursor;",
            "} while (cursor);",
            "for (const line of receipt.lines) {",
            "  const id = await items.create('Receipt lines', { title: line.description, quantity: line.quantity, unitPrice: line.unitPrice ?? null, amount: line.amount });",
            "  await items.relate(item.id, id, 'contains receipt line');",
            "}",
            "log(`${receipt.store}: ${receipt.lines.length} lines`);",
            "return { lines: receipt.lines.length };"
          ]
        },
        "next": {
          "error": "review"
        }
      },
      "review": {
        "activity": "item.update",
        "inputs": {
          "fields": {
            "status": "Needs review"
          }
        }
      },
      "prepare": {
        "activity": "paperdotnet.storageoptimization.prepare",
        "next": {
          "candidate": "optimize review",
          "skipped": "is receipt"
        }
      },
      "optimize review": {
        "activity": "approval",
        "inputs": {
          "title": "Review smaller file for {title}",
          "assignees": "{step:prepare.approvers}",
          "review": {
            "type": "paperdotnet.storageoptimization.image",
            "key": "{step:prepare.candidate}"
          }
        },
        "next": {
          "approved": "accept optimized",
          "rejected": "keep original"
        }
      },
      "accept optimized": {
        "activity": "paperdotnet.storageoptimization.accept",
        "inputs": {
          "candidate": "{step:prepare.candidate}"
        },
        "next": {
          "done": "is receipt"
        }
      },
      "keep original": {
        "activity": "paperdotnet.storageoptimization.discard",
        "inputs": {
          "candidate": "{step:prepare.candidate}"
        },
        "next": {
          "done": "is receipt"
        }
      },
      "is receipt": {
        "activity": "item.hasTerms",
        "inputs": {
          "terms": [
            "Receipts/Tags/{parameter:Tag}"
          ]
        },
        "next": {
          "matched": "read"
        }
      }
    }
  }
}
